const projects=[
{title:'A knowledge base that actually answers',category:'AI & automation',art:'ai',name:'Maya Chen',role:'AI product engineer',initials:'MC',desc:'Turning scattered team knowledge into answers you can trust.',query:'AI knowledge base search documents retrieval',question:'How do you help a team find a reliable answer without asking them to learn another tool?',approach:'Start with a narrow collection of reviewed documents. Retrieve relevant passages before generating an answer, and show the source beside every claim. Make “I don’t know” a useful outcome.',tradeoff:'A smaller, reviewed knowledge set produces fewer answers, but makes it easier to investigate mistakes. Freshness and ownership matter as much as retrieval quality.',lesson:'Measure whether someone found a supported answer, rather than whether the assistant replied. Give document owners a queue of unanswered questions.'},
{title:'A marketplace for the beautifully niche',category:'Platforms',art:'market',name:'Oliver Park',role:'Marketplace strategist',initials:'OP',desc:'Connecting independent makers with people who care about craft.',query:'marketplace niche commerce makers',question:'How does a small marketplace create useful matches before it has scale?',approach:'Choose one narrow buyer need and recruit a small set of suppliers by hand. Curate the first listings around comparable attributes and learn from unsuccessful searches.',tradeoff:'Manual curation slows expansion but reveals what buyers really need to compare. A large catalog can hide a lack of useful matches.',lesson:'Validate repeated buyer demand before automating seller onboarding. Density within a niche matters more than total listing count.'},
{title:'From sign-up to the first small win',category:'Product & design',art:'onboard',name:'Sofia Reyes',role:'Product designer',initials:'SR',desc:'Rethinking onboarding around progress, not product tours.',query:'onboarding signup activation product design',question:'What should a new user accomplish before we ask them to configure anything?',approach:'Map the smallest useful outcome, then remove every setup step that is not needed for it. Use an editable example so the first session begins with progress.',tradeoff:'Delaying configuration makes the first session simpler, but requires careful defaults and a clear path to adjust them later.',lesson:'Track time to a meaningful outcome. Tour completion can look healthy while users still struggle to begin.'},
{title:'A smaller, more meaningful community',category:'Community',art:'community',name:'Theo Williams',role:'Community builder',initials:'TW',desc:'Designing for conversations worth coming back to.',query:'community members conversations groups',question:'How do you create participation without an endless feed?',approach:'Organize small groups around a shared challenge. Use a recurring prompt, a clear host role, and a closing recap that turns discussion into reusable knowledge.',tradeoff:'Small groups limit reach but make it easier to build trust. Hosting takes effort, so the operating model must be sustainable.',lesson:'Return participation and helpful replies tell a richer story than member count.'},
{title:'Less busywork. More room to think.',category:'AI & automation',art:'ops',name:'Arjun Patel',role:'Systems designer',initials:'AP',desc:'A human-in-the-loop approach to everyday operations.',query:'automation workflow operations approval ai',question:'Which repetitive decisions can we safely take off a team’s plate?',approach:'Observe the workflow first. Automate predictable transformations, keep exceptions visible, and ask a person to approve actions with external consequences.',tradeoff:'Review steps reduce speed, but preserve accountability and expose where the automation is uncertain.',lesson:'Design the exception queue before the happy path. A useful automation makes recovery easier too.'},
{title:'A design system people want to use',category:'Product & design',art:'design',name:'Nina Okafor',role:'Design systems lead',initials:'NO',desc:'Shared principles before a shared component library.',query:'design system components library tokens',question:'How do you create consistency without slowing teams down?',approach:'Start with repeated product problems and document the reasoning behind a small set of patterns. Build components alongside the teams using them.',tradeoff:'A smaller library leaves some inconsistency, but avoids maintaining components nobody needs.',lesson:'Adoption grows when the system removes everyday friction. Explain when to use a pattern and when to choose something else.'}];
const $=id=>document.getElementById(id);let view='projects',filter='All';let requests=[],submissions=[];try{requests=JSON.parse(localStorage.getItem('knowhow-requests')||'[]');submissions=JSON.parse(localStorage.getItem('knowhow-submissions')||'[]')}catch{}const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem('knowhow-requests',JSON.stringify(requests));localStorage.setItem('knowhow-submissions',JSON.stringify(submissions));return true}catch{alert('Your browser could not save this entry. Please copy it before closing.');return false}}
function art(p){return `<div class="art ${p.art}"><div class="mini"><div class="bar"></div><strong>${p.art==='market'?'Objects with a story.':p.art==='onboard'?'Make yourself at home.':p.art==='ai'?'What would you like to know?':p.art==='community'?'A good place to begin.':p.art==='ops'?'Space for better work.':'A shared way forward.'}</strong>${p.art==='market'?'<div class="tiles"><b></b><b></b><b></b></div>':'<div class="fake-search">'+(p.art==='ai'?'Ask a question about your team’s knowledge':'Let’s start with something small')+'</div><div class="lines"><i></i><i></i><i></i></div>'}</div></div>`}
function render(){const q=$('search').value.toLowerCase().trim();$('sectionLabel').textContent=view==='projects'?'THE PROJECT LIBRARY':view==='people'?'THE MINDS BEHIND THE WORK':'IDEAS LOOKING FOR THEIR PEOPLE';$('sectionTitle').textContent=view==='projects'?(q?'Find your starting point.':'Start with a possibility.'):view==='people'?'Find someone who gets it.':'Start a new possibility.';$('filters').hidden=view==='requests';let list=projects.filter(p=>(filter==='All'||p.category===filter)&&(!q||`${p.title} ${p.category} ${p.name} ${p.query}`.toLowerCase().includes(q)));if($('sort').value==='title')list.sort((a,b)=>a.title.localeCompare(b.title));if(view==='requests'){$('grid').innerHTML=requests.filter(r=>!q||`${r.title} ${r.details}`.toLowerCase().includes(q)).map(r=>`<article class="card request-card"><span class="tag">LOCAL PROJECT REQUEST</span><h3>${esc(r.title)}</h3><p>${esc(r.details)}</p><span class="status">Saved on this device · ${esc(r.stage)}</span></article>`).join('')||`<div class="empty"><h3>A good question is a great start.</h3><p>No requests here yet. Describe what you want to build.</p><button class="dark" onclick="requestForm()">Post the first request</button></div>`;return}$('grid').innerHTML=list.map(p=>view==='people'?`<button class="card person-card" data-person="${projects.indexOf(p)}"><div class="avatar">${p.initials}</div><h3>${p.name}</h3><span class="tag">${p.role}</span><p style="margin-top:16px">${p.desc}</p><span class="status">Explore their thinking</span></button>`:`<button class="card" data-project="${projects.indexOf(p)}">${art(p)}<div class="card-body"><span class="tag">${p.category}</span><h3>${p.title}</h3><p>${p.desc}</p><div class="person"><span class="avatar">${p.initials}</span><span>${p.name}<small>${p.role}</small></span><span class="read">Read the thinking</span></div></div></button>`).join('')||`<div class="empty"><h3>This idea hasn’t found its case study yet.</h3><p>Try fewer words, explore another category, or request the knowhow you need.</p><button class="dark" onclick="requestForm()">Request this project</button></div>`}
function open(html){$('modal').innerHTML=html;if(!$('dialog').open)$('dialog').showModal()}
function project(i){const p=projects[i];open(`<span class="tag">${p.category} · Illustrative case study</span><h2>${p.title}</h2><p>${p.question}</p><h3>The approach</h3><p>${p.approach}</p><h3>The tradeoff</h3><p>${p.tradeoff}</p><h3>What to take with you</h3><p>${p.lesson}</p><button class="dark" onclick="person(${i})">Meet ${p.name.split(' ')[0]}</button>`)}
function person(i){const p=projects[i];open(`<span class="tag">EXAMPLE PROFILE</span><h2>${p.name}</h2><p>${p.role} · ${p.category}</p><h3>How I think about the work</h3><p>${p.approach}</p><h3>Explore the project</h3><p>${p.title}</p><button class="outline" onclick="project(${i})">Read the case study</button><h3>Have a related challenge?</h3><p>This is an illustrative profile. You can save a project brief locally, ready to share with a real collaborator.</p><button class="dark" onclick="requestForm('${p.name}')">Create a related brief</button>`)}
function requestForm(name=''){open(`<span class="tag">START WITH THE QUESTION</span><h2>What do you want to build?</h2><p>Describe the outcome and the thinking you need. This prototype saves requests on this device; it doesn’t send them to anyone.</p><form id="entry"><label for="title">Your project idea</label><input id="title" required maxlength="120" placeholder="I want to build…" value="${esc($('search').value)}"><label for="details">What are you trying to achieve?</label><textarea id="details" required maxlength="3000" placeholder="Who is it for? What have you tried? Where are you stuck?">${name?esc('Inspired by '+name+'’s example project. '):''}</textarea><label for="stage">Where are you now?</label><select id="stage"><option>Exploring an idea</option><option>Planning an approach</option><option>Building a first version</option><option>Improving something existing</option></select><button class="dark">Save project request</button></form>`);$('entry').onsubmit=e=>{e.preventDefault();const r={title:$('title').value.trim(),details:$('details').value.trim(),stage:$('stage').value};if(!r.title||!r.details)return;requests.unshift(r);if(save()){$('dialog').close();$('search').value='';setView('requests')}}}
function share(){open(`<span class="tag">THE REASONING IS THE STORY</span><h2>Share your thinking.</h2><p>Capture a case study draft on this device. Explain the decisions, not just the result.</p><form id="entry"><label for="title">Project title</label><input id="title" required maxlength="120"><label for="details">The problem, your approach, and the tradeoffs</label><textarea id="details" required maxlength="5000" placeholder="What did you choose, why, and what would you do differently?"></textarea><button class="dark">Save case study draft</button></form>${submissions.length?'<h3>Your saved drafts</h3>'+submissions.map(s=>`<details><summary>${esc(s.title)}</summary><p style="white-space:pre-wrap">${esc(s.details)}</p></details>`).join(''):''}`);$('entry').onsubmit=e=>{e.preventDefault();const s={title:$('title').value.trim(),details:$('details').value.trim()};if(!s.title||!s.details)return;submissions.unshift(s);if(save())open('<span class="tag">DRAFT SAVED ON THIS DEVICE</span><h2>Your thinking has a starting point.</h2><p>Open “Share your thinking” to read your saved draft. This draft has not been published.</p>')}}
function setView(v){view=v;filter='All';document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter==='All'));document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));render()}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));render()});document.querySelectorAll('[data-query]').forEach(b=>b.onclick=()=>{$('search').value=b.dataset.query;setView('projects')});$('searchForm').onsubmit=e=>{e.preventDefault();render();$('sectionTitle').scrollIntoView({behavior:'smooth',block:'center'})};$('search').oninput=render;$('sort').onchange=render;$('grid').onclick=e=>{const p=e.target.closest('[data-project]'),n=e.target.closest('[data-person]');if(p)project(+p.dataset.project);if(n)person(+n.dataset.person)};$('request').onclick=()=>requestForm();$('share').onclick=share;document.querySelector('.close').onclick=()=>$('dialog').close();$('dialog').onclick=e=>{if(e.target===$('dialog')){const r=$('dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('dialog').close()}};render();

// Keep the opening question steady while its project changes.
const rotatingProject = document.getElementById('rotatingProject');
const projectQuestions = [
  'a CRM for tracking leads on an e-commerce system?',
  'a conversational-based onboarding experience?',
  'an AI knowledge base that answers with sources?',
  'a marketplace for independent makers?',
  'a community built around meaningful conversations?'
];
const motionPreference = window.matchMedia('(prefers-reduced-motion: reduce)');
let questionIndex = 0;
let questionTimer;
let transitionTimer;
function stopQuestions() { clearTimeout(questionTimer); clearTimeout(transitionTimer); rotatingProject.classList.remove('is-changing'); }
function queueQuestion() {
  if (motionPreference.matches || document.hidden) return;
  questionTimer = setTimeout(() => {
    rotatingProject.classList.add('is-changing');
    transitionTimer = setTimeout(() => {
      questionIndex = (questionIndex + 1) % projectQuestions.length;
      rotatingProject.textContent = projectQuestions[questionIndex];
      rotatingProject.classList.remove('is-changing');
      queueQuestion();
    }, 450);
  }, 4800);
}
document.addEventListener('visibilitychange', () => { stopQuestions(); queueQuestion(); });
motionPreference.addEventListener('change', () => { stopQuestions(); queueQuestion(); });
queueQuestion();
